settings.custom_css:
.elementor-image-carousel-wrapper {
  overflow: visible;
}

/* Mantém o carrossel fluido */
selector .swiper-wrapper {
  transition-timing-function: linear !important;
}

/* 🌫️ Aplica blur leve somente no conteúdo dentro do carrossel */
.elementor-image-carousel-wrapper * {
  filter: blur(0px);
  opacity: 0.95;
  transition: filter 0.3s ease-in-out;
}

/* Opcional: reduz o blur ao passar o mouse (efeito de foco suave) */
.elementor-image-carousel-wrapper:hover * {
  filter: blur(0.8px);
  opacity: 1;
}

selector .elementor-heading-title {
   background: linear-gradient(to right, #B5795A, #D4B19F);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

selector::before {
content:"";
display: block;
width: 100%;
height: 100%;
position: absolute;
z-index: 999;
background: linear-gradient(90deg, #FCF9F7, transparent 15%, transparent 85%, #FCF9F7 100%);
pointer-events:none;
}
